package dev.pocketengine.features.local.project;
import static org.junit.Assert.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import org.json.*;import org.junit.*;
public final class ProjectDirectoryCreateTest {
 private Path root;
 @Before public void create()throws Exception{root=Files.createTempDirectory("pw-directory-create-");}
 @After public void close()throws Exception{try(var paths=Files.walk(root)){for(Path path:paths.sorted(Comparator.reverseOrder()).toArray(Path[]::new))Files.deleteIfExists(path);}}
 private JSONObject edit(String path)throws Exception{return new JSONObject().put("action","mkdir").put("path",path);}
 private JSONArray plan(JSONObject edit)throws Exception{return ProjectDirectoryCreate.prepare(root.toFile(),edit,()->{});}
 private JSONObject run(JSONArray rows)throws Exception{return ProjectDirectoryCreate.execute(root.toFile(),rows,()->{});}
 @Test public void oneRealDirectoryIsCreatedWithTypedStateNotAZeroLengthFile()throws Exception{JSONArray rows=plan(edit("empty"));assertFalse(Files.exists(root.resolve("empty")));assertEquals("directory",rows.getJSONObject(0).getString("resourceKind"));assertFalse(rows.toString().contains("content"));JSONObject result=run(rows);assertEquals(result.toString(),"completed",result.getString("status"));assertTrue(Files.isDirectory(root.resolve("empty")));assertTrue(result.getBoolean("receiptReceived"));assertTrue(result.getBoolean("fileCommitAttempted"));assertFalse(result.getBoolean("replayAllowed"));assertEquals("created",result.getJSONArray("files").getJSONObject(0).getString("directoryOutcome"));assertEquals(1,result.getJSONArray("files").getJSONObject(0).getJSONArray("createdPaths").length());assertEquals(0,result.getInt("appliedFiles"));}
 @Test public void existingDirectoryIsObservedAlreadyExistsWithoutCallingMkdirOrRewritingAnything()throws Exception{Files.createDirectory(root.resolve("existing"));Files.write(root.resolve("existing/keep"),new byte[]{9});JSONObject result=run(plan(edit("existing")));assertEquals("completed",result.getString("status"));assertFalse(result.getBoolean("fileCommitAttempted"));assertEquals("already_exists",result.getJSONArray("files").getJSONObject(0).getString("directoryOutcome"));assertEquals(0,result.getJSONArray("files").getJSONObject(0).getJSONArray("createdPaths").length());assertArrayEquals(new byte[]{9},Files.readAllBytes(root.resolve("existing/keep")));}
 @Test public void parentsAreOnlyCreatedWhenExplicitlySelectedAndEachPathIsReported()throws Exception{assertThrows(IllegalArgumentException.class,()->plan(edit("a/b/c")));assertFalse(Files.exists(root.resolve("a")));JSONArray rows=plan(edit("a/b/c").put("createParents",true));assertEquals(3,rows.getJSONObject(0).getJSONObject("directoryPlan").getJSONArray("missingPaths").length());JSONObject result=run(rows);assertEquals(result.toString(),"completed",result.getString("status"));assertTrue(Files.isDirectory(root.resolve("a/b/c")));JSONArray created=result.getJSONArray("files").getJSONObject(0).getJSONArray("createdPaths");assertEquals(3,created.length());assertEquals("a",created.getJSONObject(0).getString("path"));assertEquals("a/b/c",created.getJSONObject(2).getString("path"));}
 @Test public void filesLinksUnsafePathsAndForgedDescriptorsCannotBecomeDirectoryWrites()throws Exception{Files.write(root.resolve("file"),new byte[]{1});Files.createDirectory(root.resolve("actual"));Files.createSymbolicLink(root.resolve("link"),root.resolve("actual"));for(String path:new String[]{"file","file/child","link","link/child","../escape","/tmp/escape",".git/new","node_modules/new","build/new","","a/"})assertThrows(Exception.class,()->plan(edit(path).put("createParents",true)));assertThrows(IllegalArgumentException.class,()->plan(edit("safe").put("content","not file content")));assertThrows(IllegalArgumentException.class,()->plan(edit("safe").put("createParents","true")));JSONArray rows=plan(edit("safe"));rows.getJSONObject(0).getJSONObject("directoryPlan").put("missingPaths",new JSONArray().put("elsewhere"));assertThrows(SecurityException.class,()->ProjectDirectoryCreate.descriptor(rows));assertArrayEquals(new byte[]{1},Files.readAllBytes(root.resolve("file")));}
 @Test public void parentOrTargetDriftInvalidatesTheOldReviewBeforeAnyMkdirDispatch()throws Exception{JSONArray rows=plan(edit("planned"));Files.write(root.resolve("owner-new"),new byte[]{7});JSONObject result=run(rows);assertEquals("failed",result.getString("status"));assertFalse(result.getBoolean("fileCommitAttempted"));assertFalse(Files.exists(root.resolve("planned")));JSONArray target=plan(edit("new-target"));Files.createDirectory(root.resolve("new-target"));JSONObject changed=run(target);assertEquals("failed",changed.getString("status"));assertFalse(changed.getBoolean("fileCommitAttempted"));assertTrue(Files.isDirectory(root.resolve("new-target")));}
 @Test public void collisionAfterAdmissionStaysUnknownEvenWhenTheLocalMkdirRaisedAlreadyExists()throws Exception{JSONArray rows=plan(edit("target"));AtomicInteger before=new AtomicInteger();ProjectDirectoryCreate.preflight(root.toFile(),rows,before::incrementAndGet);AtomicInteger calls=new AtomicInteger();JSONObject unknown=ProjectDirectoryCreate.execute(root.toFile(),rows,()->{if(calls.incrementAndGet()==before.get()+3)Files.write(root.resolve("target"),new byte[]{8});});assertEquals(unknown.toString(),"unknown",unknown.getString("status"));assertFalse(unknown.getBoolean("receiptReceived"));assertTrue(unknown.getBoolean("fileCommitAttempted"));assertFalse(unknown.getBoolean("replayAllowed"));assertArrayEquals(new byte[]{8},Files.readAllBytes(root.resolve("target")));}
 @Test public void cancellationAfterOneParentPreservesActualCreatedPathsAndNeverRollsBackOrRetries()throws Exception{JSONArray rows=plan(edit("a/b/c").put("createParents",true));JSONObject unknown=ProjectDirectoryCreate.execute(root.toFile(),rows,()->{if(Files.isDirectory(root.resolve("a")))throw new InterruptedException("original cancelled after first real mkdir");});assertEquals(unknown.toString(),"unknown",unknown.getString("status"));assertTrue(Files.isDirectory(root.resolve("a")));assertFalse(Files.exists(root.resolve("a/b")));assertEquals(1,unknown.getJSONArray("files").getJSONObject(0).getJSONArray("createdPaths").length());assertFalse(unknown.getBoolean("receiptReceived"));assertTrue(unknown.isNull("partialEffects"));}
 @Test public void cancelledBeforeDispatchHasNoEffectAndDepthIsExplicitlyBounded()throws Exception{JSONArray rows=plan(edit("never"));JSONObject refused=ProjectDirectoryCreate.execute(root.toFile(),rows,()->{throw new InterruptedException("original cancelled");});assertEquals("failed",refused.getString("status"));assertFalse(refused.getBoolean("fileCommitAttempted"));assertFalse(Files.exists(root.resolve("never")));assertThrows(IllegalArgumentException.class,()->plan(edit(String.join("/",Collections.nCopies(41,"d"))).put("createParents",true)));}
}
